43e\u0432\u043e\u043c \u0438 \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e\u00a0 \u044e\u043d\u043e\u0448\u0435\u0441\u043a\u043e\u043c \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0443\u0436\u0435 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0434\u043b\u044f \u0434\u0435\u0442\u0435\u0439\u00a0 \u0442\u0430\u043a\u0438\u043c \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u043c \u0430\u0432\u0442\u043e\u0440\u0438\u0442\u0435\u0442\u043e\u043c, \u043a\u0430\u043a \u0440\u0430\u043d\u044c\u0448\u0435. \u0414\u0435\u0442\u0438 \u043d\u0430\u0447\u0438\u043d\u0430\u044e\u0442 \u0432\u043e\u0441\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0431\u043e\u043b\u0435\u0435 \u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e.\u00a0 \u0421\u0442\u0440\u0435\u043c\u043b\u0435\u043d\u0438\u0435 \u043a \u043f\u043e\u0434\u0440\u0430\u0436\u0430\u043d\u0438\u044e \u0438 \u0441\u0442\u0435\u043f\u0435\u043d\u044c\u00a0 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u0438 \u0441 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c\u0438 \u0437\u0430\u043c\u0435\u0442\u043d\u043e \u0441\u043d\u0438\u0436\u0430\u044e\u0442\u0441\u044f, \u0430 \u0432 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u0430 \u0434\u043b\u044f \u043f\u043e\u0434\u0440\u0430\u0436\u0430\u043d\u0438\u044f \u043d\u0430\u0447\u0438\u043d\u0430\u044e\u0442 \u0432\u044b\u0441\u0442\u0443\u043f\u0430\u0442\u044c \u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u043b\u044e\u0434\u0438: \u0437\u043d\u0430\u043a\u043e\u043c\u044b\u0435, \u0441\u0432\u0435\u0440\u0441\u0442\u043d\u0438\u043a\u0438, \u043f\u043e\u043f\u0443\u043b\u044f\u0440\u043d\u044b\u0435 \u043b\u0438\u0447\u043d\u043e\u0441\u0442\u0438. \u0412\u043c\u0435\u0441\u0442\u0435 \u0441 \u0442\u0435\u043c \u043f\u043e\u0434\u0440\u043e\u0441\u0442\u043a\u0438 \u0445\u043e\u0442\u044f\u0442 \u0438\u043c\u0435\u0442\u044c \u0442\u0430\u043a\u0438\u0445 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u00ab\u043f\u043e\u0434\u0430\u044e\u0442 \u0445\u043e\u0440\u043e\u0448\u0438\u0439 \u043f\u0440\u0438\u043c\u0435\u0440 \u0434\u043b\u044f \u043f\u043e\u0434\u0440\u0430\u0436\u0430\u043d\u0438\u044f\u00bb, \u00ab\u0445\u043e\u0442\u044f\u0442\u00a0 \u0433\u043e\u0440\u0434\u0438\u0442\u044c\u0441\u044f \u0441\u0432\u043e\u0438\u043c\u0438 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c\u0438, \u0432\u0438\u0434\u0435\u0442\u044c \u0438\u0445 \u043b\u044e\u0434\u044c\u043c\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u043c\u0438 \u043c\u043e\u0436\u043d\u043e \u0432\u043e\u0441\u0445\u0438\u0449\u0430\u0442\u044c\u0441\u044f\u00bb, \u0438 \u0442\u043e\u0433\u0434\u0430 \u043e\u043d\u0438, \u043a\u0430\u043a \u043f\u0440\u0430\u0432\u0438\u043b\u043e, \u0447\u0443\u0432\u0441\u0442\u0432\u0443\u044e\u0442 \u0441\u0435\u0431\u044f \u0432 \u043c\u0438\u0440\u0435 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043a\u043e\u043c\u0444\u043e\u0440\u0442\u043d\u043e.<\\\/p>\\n<p><em><strong>\u0420\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043a\u0430\u043a \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0436\u0438\u0437\u043d\u0435\u043d\u043d\u043e\u0433\u043e \u043e\u043f\u044b\u0442\u0430.<\\\/strong><\\\/em>\u00a0\u0412\u0430\u0436\u043d\u0435\u0439\u0448\u0435\u0439 \u0444\u0443\u043d\u043a\u0446\u0438\u0435\u0439 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0432 \u043f\u043e\u0434\u0440\u043e\u0441\u0442\u043a\u043e\u0432\u043e\u043c \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u043c\u043e\u0449\u044c \u0440\u0435\u0431\u0435\u043d\u043a\u0443 \u0432 \u0440\u0435\u0448\u0435\u043d\u0438\u0438 \u0441\u043b\u043e\u0436\u043d\u044b\u0445 \u0436\u0438\u0437\u043d\u04